DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='nexuslegal_app') THEN CREATE ROLE nexuslegal_app LOGIN PASSWORD 'nexuslegal_app'; END IF; END $$;
CREATE TABLE organizations(id BIGSERIAL PRIMARY KEY,name VARCHAR(180) NOT NULL,type VARCHAR(30) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users(id BIGSERIAL PRIMARY KEY,username VARCHAR(60) UNIQUE NOT NULL,full_name VARCHAR(160) NOT NULL,email VARCHAR(160) NOT NULL,role VARCHAR(50) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE memberships(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id),organization_id BIGINT REFERENCES organizations(id),role VARCHAR(60) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',expires_at DATE);
CREATE TABLE companies(id BIGSERIAL PRIMARY KEY,organization_id BIGINT REFERENCES organizations(id),legal_name VARCHAR(180) NOT NULL,tax_id VARCHAR(30) UNIQUE NOT NULL,segment VARCHAR(80) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',annual_revenue NUMERIC(15,2) DEFAULT 0);
CREATE TABLE individual_clients(id BIGSERIAL PRIMARY KEY,organization_id BIGINT REFERENCES organizations(id),full_name VARCHAR(160) NOT NULL,document VARCHAR(30) UNIQUE NOT NULL,email VARCHAR(160) NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE matters(id BIGSERIAL PRIMARY KEY,organization_id BIGINT REFERENCES organizations(id),client_type VARCHAR(20) NOT NULL,client_id BIGINT NOT NULL,title VARCHAR(220) NOT NULL,area VARCHAR(80) NOT NULL,status VARCHAR(30) NOT NULL,priority VARCHAR(20) NOT NULL,responsible_user_id BIGINT REFERENCES users(id),next_deadline DATE,value NUMERIC(15,2) DEFAULT 0);
CREATE TABLE obligations(id BIGSERIAL PRIMARY KEY,organization_id BIGINT REFERENCES organizations(id),company_id BIGINT REFERENCES companies(id),title VARCHAR(220) NOT NULL,obligation_type VARCHAR(70) NOT NULL,due_date DATE NOT NULL,status VARCHAR(24) NOT NULL,amount NUMERIC(15,2) DEFAULT 0,responsible_user_id BIGINT REFERENCES users(id));
CREATE TABLE documents(id BIGSERIAL PRIMARY KEY,organization_id BIGINT REFERENCES organizations(id),matter_id BIGINT REFERENCES matters(id),company_id BIGINT REFERENCES companies(id),title VARCHAR(220) NOT NULL,category VARCHAR(70) NOT NULL,content TEXT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'ACTIVE',owner_user_id BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE tasks(id BIGSERIAL PRIMARY KEY,organization_id BIGINT REFERENCES organizations(id),title VARCHAR(220) NOT NULL,due_date DATE NOT NULL,status VARCHAR(24) NOT NULL,priority VARCHAR(20) NOT NULL,assigned_user_id BIGINT REFERENCES users(id));
CREATE TABLE audit_events(id BIGSERIAL PRIMARY KEY,organization_id BIGINT REFERENCES organizations(id),actor_user_id BIGINT REFERENCES users(id),action VARCHAR(90) NOT NULL,resource VARCHAR(100) NOT NULL,details TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_memberships_user ON memberships(user_id,organization_id); CREATE INDEX idx_matters_org ON matters(organization_id); CREATE INDEX idx_obligations_org ON obligations(organization_id); CREATE INDEX idx_documents_org ON documents(organization_id);
